type DeviceState = Extract<TopologyNodeState,'mainline'|'workspace-added'|'workspace-modified'>;
type RoleSource = 'Assigned' | 'Discovered metadata' | 'Demo hostname fallback' | 'Unclassified';
type NodeIdSource = 'Auto' | 'Override';
export type Device = { id:string; hostname:string; managementIp:string; mac:string; model:string; interfaces:number; os:string; sourceWorkspace:string; role:TopologyRole; customRole?:string; roleSource:RoleSource; nodeId?:string; autoNodeId?:string; nodeIdSource?:NodeIdSource; state:DeviceState };
type UpdateStatus = 'New' | 'Ignored';
type ConnectionPayload = { sourceDeviceId:string; sourceInterface:string; targetDeviceId:string; targetInterface:string; speed:string; confidence:'High'|'Medium' };
type DiscoveredDevicePayload = { id:string; managementIp:string; mac:string; model:string; os:string; nodeId:string; customRole?:string };
export type Update = { id:string; kind:'Device Added'|'Interface Changed'; details:string; status:UpdateStatus; hostname:string; interfaces:number; detected:string; source:string; confidence:'High'|'Medium'; role?:TopologyRole; device?:DiscoveredDevicePayload; connection?:ConnectionPayload; conflict?:string };
export type InventoryTopologyState = { registered:Device[]; updates:Update[]; connections:TopologyLink[]; removedConnectionIds:string[]; acceptedTotal:number };
type Props = { onBack:()=>void; initialTab?:'devices'|'updates'; onTabChange?:(tab:'devices'|'updates')=>void; initialWorkspace?:string; onWorkspaceChange?:(workspace:string)=>void; initialState?:InventoryTopologyState; onStateChange?:(state:InventoryTopologyState)=>void };
type Snapshot = InventoryTopologyState;
type InterfaceDraft = { localInterface:string; neighborDeviceId:string; neighborInterface:string };
